import subprocess


class EthInterfaces(object):
    @staticmethod
    def get_eth_ip(eth_name, remote_host='127.0.0.1'):
        """
        Gets ip address of given eth interface
        :param eth_name: name of eth interface in form eth0, eth3 etc.
        :param remote_host: host IP of virtual machine from which get eth ip
        :return: ip of eth interface as string
        """
        # TODO check is for compatibility with setup_and_teardowns.robot and can be removed after the file is removed
        if not remote_host:
            remote_host = '127.0.0.1'
        eth_ip = subprocess.Popen(
            [
                r"ssh {0} ip address show label {1} | grep 'inet ' | head -n1 | "
                r"sed -r 's:.*inet (.+?)/.*:\1:'".format(remote_host, eth_name)
            ],
            shell=True,
            stdout=subprocess.PIPE,
        ).communicate()[0]
        return eth_ip.decode("utf-8").strip()

    @staticmethod
    def get_eth_scope_global_ips(eth_name, remote_host='127.0.0.1'):
        """
        Gets ip addreses of given eth interface
        :param eth_name: name of eth interface in form eth0, eth3 etc.
        :param remote_host: host IP of virtual machine from which get eth ip
        :return: ips of eth interface as a list
        """
        # TODO check is for compatibility with setup_and_teardowns.robot and can be removed after the file is removed
        if not remote_host:
            remote_host = '127.0.0.1'
        eth_ips = subprocess.Popen(
            [
                r"ssh {0} ip address show label {1} | grep 'inet' | grep 'scope global' | "
                r"sed -r 's:.*inet6? (.+?)/.*:\1:'".format(remote_host, eth_name)
            ],
            shell=True,
            stdout=subprocess.PIPE,
        ).communicate()[0]
        return eth_ips

    @staticmethod
    def get_hostname(remote_host='127.0.0.1'):
        """
        Gets hostname from given remote host virtual machine
        :param remote_host: virtual machines ip address
        :return: hostname as string
        """
        if not remote_host:
            remote_host = '127.0.0.1'
        vm_hostname = subprocess.Popen(
            ["ssh {0} hostname".format(remote_host)], shell=True, stdout=subprocess.PIPE
        ).communicate()[0]
        return vm_hostname.strip()
